def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max((v for row in grid for v in row),
             key=lambda v: sum(row.count(v) for row in grid))
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    if not cells:
        return [row[:] for row in grid]

    r0 = min(r for r, c in cells)
    r1 = max(r for r, c in cells)
    c0 = min(c for r, c in cells)
    c1 = max(c for r, c in cells)
    out = [row[:] for row in grid]

    # Complete the perimeter of the bounding rectangle.
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            if r in (r0, r1) or c in (c0, c1):
                if grid[r][c] == bg:
                    out[r][c] = 2

    # Complete one-cell gaps between same-colored marks on a line.
    for r in range(h):
        for c in range(1, w - 1):
            if (grid[r][c] == bg and grid[r][c - 1] != bg
                    and grid[r][c + 1] == grid[r][c - 1]):
                out[r][c] = 2
    for c in range(w):
        for r in range(1, h - 1):
            if (grid[r][c] == bg and grid[r - 1][c] != bg
                    and grid[r + 1][c] == grid[r - 1][c]):
                out[r][c] = 2

    return out
